import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    strings = input[1:]

    # Create a dictionary to store suffixes
    suffix_dict = defaultdict(list)

    # Populate the dictionary with suffixes
    for i, s in enumerate(strings):
        for j in range(len(s)):
            suffix = s[j:]
            suffix_dict[suffix].append(i)

    # Find the longest chain of suffixes
    max_chain_length = 0
    visited = [False] * n

    def dfs(node):
        if visited[node]:
            return 0
        visited[node] = True
        max_length = 1
        current_string = strings[node]
        for i in range(1, len(current_string)):
            suffix = current_string[i:]
            if suffix in suffix_dict:
                for next_node in suffix_dict[suffix]:
                    if not visited[next_node]:
                        max_length = max(max_length, 1 + dfs(next_node))
        return max_length

    for i in range(n):
        if not visited[i]:
            max_chain_length = max(max_chain_length, dfs(i))

    print(max_chain_length)

if __name__ == "__main__":
    main()
